#!/bin/bash
# archive_copy <dir> <archive dir> <name> <stamp>: copy name.1 to <archive dir>/name.<stamp>.
archive_copy() {
  local dir=$1 archive=$2 name=$3 stamp=$4
  mkdir -p "$archive"
  cp "$dir/$name.1" "$archive/$name.$stamp"
}


# prune_archive <archive dir> <name> <keep>: keep only the newest <keep> of name.<YYYYMMDD> (by date).
prune_archive() {
  local archive=$1 name=$2 keep=$3 f suffix
  for f in "$archive"/*; do
    f=${f##*/}
    case $f in "$name".*) ;; *) continue ;; esac
    suffix=${f#"$name".}
    case $suffix in [0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]) echo "$suffix" ;; esac
  done | sort -r | tail -n +"$((keep + 1))" | while read -r suffix; do
    rm -f -- "$archive/$name.$suffix"
  done
}

lib/local.sh.text:
#!/bin/bash
# rotate_local <dir> <name>: name.N -> name.N+1, name -> name.1, then a new empty name.
rotate_local() {
  local dir=$1 name=$2 n
  n=$(ls "$dir" | grep -c "^$name\.[0-9][0-9]*$")
  while [ "$n" -ge 1 ]; do
    mv "$dir/$name.$n" "$dir/$name.$((n + 1))"
    n=$((n - 1))
  done
  mv "$dir/$name" "$dir/$name.1"
  : > "$dir/$name"
}


# prune_local <dir> <name> <keep>: remove name.N for N > keep (exact "name.<digits>" only).
prune_local() {
  local dir=$1 name=$2 keep=$3 f suffix
  for f in "$dir"/*; do
    f=${f##*/}
    case $f in "$name".*) ;; *) continue ;; esac
    suffix=${f#"$name".}
    case $suffix in ''|*[!0-9]*) continue ;; esac
    [ "$((10#$suffix))" -gt "$keep" ] && rm -f -- "$dir/$f"
  done
}

