#!/bin/bash
# archive_copy <dir> <archive dir> <name> <stamp> <keep>: copy name.1 to <archive dir>/name.<stamp>,
# then delete all but the newest <keep> files named exactly name.<8 digits>.
archive_copy() {
  local dir=$1 archive=$2 name=$3 stamp=$4 keep=$5 files i
  mkdir -p "$archive"
  cp "$dir/$name.1" "$archive/$name.$stamp"
  files=("$archive/$name".[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9])  # glob sorts oldest first
  for ((i = 0; i < ${#files[@]} - keep; i++)); do rm -f -- "${files[i]}"; done
}

